package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer.writeNumber(float f)
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    @Test
    public void testWriteNumberFloat_Positive() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        float value = 123.45f;

        buffer.writeNumber(value);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(123.45f, parser.getFloatValue(), 0.0001f);
    }

    @Test
    public void testWriteNumberFloat_Negative() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        float value = -0.001f;

        buffer.writeNumber(value);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(-0.001f, parser.getFloatValue(), 0.0001f);
    }

    @Test
    public void testWriteNumberFloat_Zero() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        float value = 0.0f;

        buffer.writeNumber(value);

        JsonParser parser = buffer.asParser();
        // Jackson might treat 0.0 as VALUE_NUMBER_FLOAT or VALUE_NUMBER_INT depending on implementation, 
        // but the method specifically calls _append(JsonToken.VALUE_NUMBER_FLOAT, ...)
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(0.0f, parser.getFloatValue(), 0.0f);
    }

    @Test
    public void testWriteNumberFloat_Infinity() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        float value = Float.POSITIVE_INFINITY;

        buffer.writeNumber(value);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(Float.POSITIVE_INFINITY, parser.getFloatValue());
    }

    @Test
    public void testWriteNumberFloat_NaN() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        float value = Float.NaN;

        buffer.writeNumber(value);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertTrue(Float.isNaN(parser.getFloatValue()));
    }

    @Test
    public void testWriteNumberFloat_LargeValue() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        float value = Float.MAX_VALUE;

        buffer.writeNumber(value);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(Float.MAX_VALUE, parser.getFloatValue());
    }
}
